package com.team2.wellness.engagement.notification.application;
import com.team2.wellness.common.api.ApiException; import com.team2.wellness.engagement.notification.domain.Notification; import com.team2.wellness.engagement.notification.persistence.NotificationRepository; import com.team2.wellness.engagement.port.out.PushNotificationPort; import jakarta.transaction.Transactional; import java.time.Instant; import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service @Transactional public class NotificationService { private final NotificationRepository repo; private final PushNotificationPort push; public NotificationService(NotificationRepository repo,PushNotificationPort push){this.repo=repo;this.push=push;} public Notification create(UUID user,String type,String content){Notification n=repo.save(new Notification(user,type,content));try{push.send(new PushNotificationPort.PushCommand(user,"Wellness",content,Map.of("notificationId",n.getId().toString())));}catch(RuntimeException ignored){}return n;} public List<Notification> page(UUID user,Instant at,UUID id,int size){return repo.page(user,at,id,PageRequest.of(0,Math.min(100,Math.max(1,size))));} public void read(UUID user,UUID id){Notification n=repo.findById(id).filter(x->x.getUserId().equals(user)).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOTIFICATION_NOT_FOUND","Notification not found"));n.markRead();} public void readAll(UUID user){repo.findByUserIdAndReadAtIsNull(user).forEach(Notification::markRead);} }
